```c
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_full  = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;
int count = 0;

void producer(int item) {
    pthread_mutex_lock(&mutex);
    while (count == CAPACITY)
        pthread_cond_wait(&not_full, &mutex);   // wait for space
    buffer_put(item);
    count++;
    pthread_cond_signal(&not_empty);            // wake a consumer
    pthread_mutex_unlock(&mutex);
}

void consumer() {
    pthread_mutex_lock(&mutex);
    while (count == 0)
        pthread_cond_wait(&not_empty, &mutex);  // wait for an item
    int item = buffer_get();
    count--;
    pthread_cond_signal(&not_full);             // wake a producer
    pthread_mutex_unlock(&mutex);
}
```

Compare this to the semaphore version: one mutex protects `count` and the buffer directly, and each condition variable expresses one specific predicate over that shared state (`not_full`, `not_empty`) instead of a standalone counter. The `while` loop, not `if`, is load-bearing — the next slide is entirely about why.
